<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Permohonan Bunker</title><style><?php if(empty($pdf_mode)): ?>@page{size:A4;margin:22mm}<?php endif; ?>body{font-family:"Times New Roman",serif;font-size:11pt;line-height:1.25;color:#111}.paper{max-width:170mm;margin:auto}table{width:100%;border-collapse:collapse}td{vertical-align:top}.meta td{padding:1px}.details td{padding:2px}.sign{margin-left:55%;text-align:center;margin-top:14mm}button{margin:10px}@media print{button{display:none}}h2{font-size:16pt;margin:0 0 12mm;color:#185e82}</style></head><body><?php if(empty($pdf_mode)): ?><button onclick="window.print()">Print / Save as PDF</button><?php endif; ?><div class="paper"><h2><?= html_escape($s['IssuerName']) ?></h2><table class="meta"><tr><td style="width:65%">Nomor &nbsp; : <?= html_escape($request['RequestNo']) ?><br>Lampiran : 1 (satu) berkas<br>Perihal &nbsp; : Surat Permohonan Pengawasan<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Bunker</td><td><?= html_escape($s['Place'].', '.date('d-m-Y',strtotime($request['RequestDate']))) ?><br><br>Kepada Yth.<br><?= nl2br(html_escape($s['Recipient'])) ?><br>Di-<br><u><?= html_escape($s['RecipientPlace']) ?></u></td></tr></table><p style="margin-top:9mm">Dengan Hormat,<br>Bersama ini kami mengajukan permohonan pengisian bahan bakar untuk kapal-kapal di Pelabuhan penyeberangan <?= html_escape($s['ArrivalPort']) ?>, kiranya diadakan pengawasan untuk pengisian Bahan Bakar Minyak yang akan dilakukan pada:</p><table class="details">
<?php $fields=array('VesselName'=>'Nama Kapal','Flag'=>'Bendera','GrossTonnage'=>'DWT/GT','VesselType'=>'Jenis Kapal','CompanyName'=>'Nama Perusahaan','MainTank'=>'Kapasitas Tangki Utama','DailyTank'=>'Kapasitas Tangki Harian','RemainingFuel'=>'Sisa BBM saat ini','PlannedLiters'=>'Rencana Bunker','Supplier'=>'Suplayer','OriginPort'=>'Datang dari','ArrivalPort'=>'Kapal Tiba','FillingDate'=>'Rencana Pengisian Tangki','Position'=>'Posisi Kapal','Captain'=>'Nakhoda');$i=0;foreach($fields as $k=>$label): ?><tr><td style="width:5%"><?= ++$i ?>.</td><td style="width:43%"><?= $label ?></td><td>: <?= html_escape($k==='PlannedLiters'?number_format($s[$k],3,',','.').' Liter':($k==='FillingDate'?date('d-m-Y',strtotime($s[$k])):$s[$k])) ?></td></tr><?php endforeach; ?></table><p style="margin-top:8mm">Demikian kami sampaikan, atas kerjasamanya kami ucapkan terima kasih.</p><div class="sign">Hormat Kami,<br><?= html_escape($s['SignatoryTitle']) ?><br><br><br><br><br><?= html_escape($s['Signatory']) ?></div></div></body></html>